Here is the commit message:
core: fix D-Bus API

This fixes bugs introduced by cffaed83e87bde81378b2be74192193850d0e03a.

Closes #7129.

Here is the root cause:
The bug was caused by improper handling of D-Bus API properties, specifically in the way the `SystemCallFilter` and `RestrictAddressFamilies` were being appended to the bus message. The previous implementation directly appended basic types and strings without proper encapsulation, leading to potential memory management issues and incorrect data structures being sent over D-Bus. The changes made in the patch address these issues by using a string vector for dynamic string handling and ensuring the correct opening and closing of message containers.

Here is the patch:

 int bus_append_unit_property_assignment(sd_bus_message *m, const char *assignment) {
         const char *eq, *field;
         UnitDependency dep;
         int r, rl;

         assert(m);
         assert(assignment);

         eq = strchr(assignment, '=');
         if (!eq) {
                 log_error("Not an assignment: %s", assignment);
                 return -EINVAL;
         }

         r = sd_bus_message_open_container(m, SD_BUS_TYPE_STRUCT, "sv");
         if (r < 0)
                 return bus_log_create_error(r);

         field = strndupa(assignment, eq - assignment);
         eq++;

         if (streq(field, "CPUQuota")) {

                 if (isempty(eq))
                         r = sd_bus_message_append(m, "sv", "CPUQuotaPerSecUSec", "t", USEC_INFINITY);
                 else {
                         r = parse_percent_unbounded(eq);
                         if (r <= 0) {
                                 log_error_errno(r, "CPU quota '%s' invalid.", eq);
                                 return -EINVAL;
                         }

                         r = sd_bus_message_append(m, "sv", "CPUQuotaPerSecUSec", "t", (usec_t) r * USEC_PER_SEC / 100U);
                 }

                 goto finish;

         } else if (streq(field, "EnvironmentFile")) {

                 r = sd_bus_message_append(m, "sv", "EnvironmentFiles", "a(sb)", 1,
                                           eq[0] == '-' ? eq + 1 : eq,
                                           eq[0] == '-');
